+
+  await waitForMinimize();
+
+  await showNotification();
+
+  Assert.equal(
+    document.querySelectorAll("in-app-notification").length,
+    0,
+    "message is not shown when minimized"
+  );
+
+  window.restore();
+
+  await waitForNotification(true);
+
+  Assert.equal(
+    document.querySelectorAll("in-app-notification").length,
+    1,
+    "message is shown when restored"
+  );
+
+  await reset();
+});
+
